def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the single solid separator, either vertical or horizontal.
    vcuts = [c for c in range(w) if all(len(row) == w for row in grid) and len({row[c] for row in grid}) == 1]
    if vcuts:
        sep = vcuts[0]
        width = min(sep, w - sep - 1)
        first = [row[sep-width:sep] for row in grid]
        second = [row[sep+1:sep+1+width] for row in grid]
    else:
        hcuts = [r for r in range(h) if len(set(grid[r])) == 1]
        sep = hcuts[0]
        height = min(sep, h - sep - 1)
        first = [row[:] for row in grid[sep-height:sep]]
        second = [row[:] for row in grid[sep+1:sep+1+height]]
    colors1 = {x for row in first for x in row}
    colors2 = {x for row in second for x in row}
    shared = colors1 & colors2
    # The two panels share exactly one meaningful color; use it as the canvas.
    color = next(iter(shared))
    out = [[color for _ in row] for row in first]
    for r in range(len(first)):
